    {
      "id": 2,
      "claim": "This gravitational force acts continuously on Earth and points toward the Sun, providing a central inward force.",
      "evidence": "The force from step 1 is always present and aligns with the line joining Earth and Sun.",
      "weight": 0.3,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "An object in a stable orbit requires an inward (centripetal) force equal to m·v²/r.",
      "evidence": "Newton's second law applied to circular motion; centripetal acceleration a_c = v²/r.",
      "weight": 0.2,
      "depends_on": []
    },
    {
      "id": 4,
      "claim": "At 1 AU the magnitude of the Sun’s gravitational force (≈3.5×10²² N) matches the required centripetal force for Earth’s orbital speed (~30 km/s).",
      "evidence": "Compute F_grav = G·M_sun·M_earth / r² ≈ 3.5×10²² N; compute F_c = M_earth·v²/r with v≈29.8 km/s gives ≈3.5×10²² N.",
      "weight": 0.1,
      "depends_on": [1, 2, 3]
    },
    {
      "id": 5,
      "claim": "Therefore the Sun’s gravitational pull supplies the necessary centripetal force and keeps Earth in orbit around the Sun.",
      "evidence": "Steps 2–4 show that the only sustained inward force equals the required centripetal force.",
      "weight": 0.0,
